package proto

// Image-save operations use only the existing supervisor/guest link.
const (
	FeatureImageSave    = "image.save"
	CtlImageChanges     = "changes"
	CtlImageLayerCancel = "layer.cancel"
	ImageChangesMax     = 100_000
	ImageChangesBytes   = 8 << 20
	// Pages leave space for the existing 64 KiB ctl response envelope.
	ImageChangesPageBytes = 32 << 10
)

// ImageChangesArgs reserves one bounded export on the original guest link.
// ID is generated by the supervisor, not a path or saved session identifier.
type ImageChangesArgs struct {
	Version    int    `json:"v"`
	ID         string `json:"id"`
	MaxEntries int    `json:"max_entries"`
	Offset     int    `json:"offset"`
}

// ImageChangesResult is advisory review input. It supplies no exclusion or
// scan authority, because the whole root stream is independently checked.
type ImageChangesResult struct {
	Version int      `json:"v"`
	ID      string   `json:"id"`
	Paths   []string `json:"paths"`
	Next    int      `json:"next"`
	Done    bool     `json:"done"`
}

// ImageLayerHeader claims exactly the export reserved on this same link.
// The fixed raw tar format and byte bound cannot select a guest/host path.
type ImageLayerHeader struct {
	Version  int    `json:"v"`
	ID       string `json:"id"`
	Format   string `json:"format"`
	MaxBytes int64  `json:"max_bytes"`
}

// ImageLayerCancel joins the original reserved export before its owner ends.
type ImageLayerCancel struct {
	Version int    `json:"v"`
	ID      string `json:"id"`
}
